<script>
import BaseComponent from '@primevue/core/basecomponent';
import SidebarMenuItemStyle from 'primevue/sidebarmenuitem/style';

export default {
    name: 'BaseSidebarMenuItem',
    extends: BaseComponent,
    props: {
        collapsible: {
            type: Boolean,
            default: false
        },
        open: {
            type: Boolean,
            default: undefined
        },
        defaultOpen: {
            type: Boolean,
            default: true
        },
        disabled: {
            type: Boolean,
            default: false
        },
        as: {
            type: [String, Object],
            default: 'LI'
        },
        asChild: {
            type: Boolean,
            default: false
        }
    },
    style: SidebarMenuItemStyle,
    provide() {
        return {
            $pcSidebarMenuItem: this,
            $parentInstance: this
        };
    }
};
</script>
